import org.junit.Test;
import org.traccar.Protocol;
import org.traccar.model.Position;
import org.traccar.network.Message;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import io.netty.buffer.Unpooled;
import io.netty.channel.Channel;
import io.netty.buffer.ByteBuf;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

public class WatchProtocolDecoderTest {

    @Test
    public void getHasIndexDefaultTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("watch"));

        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getManufacturerDefaultTest() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(new Protocol("watch"));

        assertEquals(decoder.getManufacturer(), "watch");
    }

    @Test
    public void decodeTest() throws Exception {
        Channel channel = mock(Channel.class);
        Protol protol = new Protocol("watch");
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(protol);

        ByteBuf buf = Unpooled.copiedBuffer("#1,1,V,A,0,122.433269,37.556769,222.00,0.000,0,800,27467780,27489400,24422500,33340000,33341600,33375500,33377100,255,255,65535,R*55\r\n", StandardCharsets.US_ASCII);

        Position position = (Position) decoder.decode(channel, new InetSocketAddress("localhost", 0), buf);

        assertEquals(position.getLatitude(), 37.556769, 0.0001);
        assertEquals(position.getLongitude(), 122.433269, 0.0001);
    }
}
